CREATE OR REPLACE FUNCTION public.nothingsports_capture_consensus_vote()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r public.nothingsports_prediction_rules;ts timestamptz:=clock_timestamp();begin
 if new.phase<>'impact' then return new;end if;
 select * into r from public.nothingsports_prediction_rules where event_id=new.event_id;
 if r.version='consensus.v1' and r.completed_at is not null and ts between r.completed_at and r.cutoff and r.settled_at is null then
  insert into public.nothingsports_consensus_votes values(new.event_id,new.user_id,new.rating,ts)
  on conflict(event_id,user_id) do update set rating=excluded.rating,recorded_at=excluded.recorded_at;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.nothingsports_enqueue_live_rating_alert()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare f record;activity uuid;group_id uuid;begin
 if new.rating<>5 or new.scoring_version<>'anticipation.v2' then return new;end if;
 if not exists(select 1 from public.nothingsports_nsc_profiles where user_id=new.user_id and visibility='visible') or exists(select 1 from public.nothingsports_nsc_personas where user_id=new.user_id and moderation_flag) then return new;end if;
 for f in select follower_user_id from public.nothingsports_user_follows where followed_user_id=new.user_id loop
 perform pg_advisory_xact_lock(hashtextextended('alert:'||f.follower_user_id||new.event_id,0));
 activity:=null;
 insert into public.nothingsports_friend_activity(recipient_user_id,rater_user_id,event_id,phase) values(f.follower_user_id,new.user_id,new.event_id,new.phase) on conflict do nothing returning id into activity;
 if activity is not null then
 select id into group_id from public.nothingsports_live_rating_alerts where recipient_user_id=f.follower_user_id and event_id=new.event_id and completed_at is null and ready_at>clock_timestamp() order by created_at desc limit 1;
 if group_id is null then insert into public.nothingsports_live_rating_alerts(recipient_user_id,event_id,ready_at) values(f.follower_user_id,new.event_id,clock_timestamp()+interval '5 minutes') returning id into group_id;end if;
 update public.nothingsports_friend_activity set alert_id=group_id where id=activity;
 end if;end loop;return new;
end $function$

CREATE OR REPLACE FUNCTION public.nothingsports_inbox_source()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare j jsonb:=to_jsonb(new); m record; k text; recipient uuid; actor uuid; pts integer:=0; source text;begin
 if tg_table_name='nothingsports_chat_messages' then
  if new.message_type='system' then return new;end if;
  -- Serialize against the receipt update to avoid reopening an already-read group.
  for m in select * from public.nothingsports_chat_members where room_id=new.room_id and user_id<>new.sender_id and member_kind='account' order by user_id for update loop
   if new.created_at<=m.last_read_at then continue;end if;
   insert into public.nothingsports_inbox(recipient_user_id,kind,source_key,actor_user_id,room_id,message_count,group_open,activity_at,created_at)
   values(m.user_id,'chat','chat:'||new.id,new.sender_id,new.room_id,1,true,new.created_at,new.created_at)
   on conflict(recipient_user_id,room_id) where group_open do update
   set message_count=nothingsports_inbox.message_count+1,actor_user_id=excluded.actor_user_id,
       activity_at=greatest(nothingsports_inbox.activity_at,excluded.activity_at),version=nothingsports_inbox.version+1,read_at=null;
  end loop;
  return new;
 elsif tg_table_name='nothingsports_chat_members' then
  if tg_op='UPDATE' then
   if new.last_read_at>old.last_read_at then
    -- Messages read before their notification is viewed need no redundant item.
    -- This also covers quiet rooms using the established 30-second polling cadence.
    delete from public.nothingsports_inbox where recipient_user_id=new.user_id and room_id=new.room_id and group_open and activity_at<=new.last_read_at and surfaced_at is null;
    update public.nothingsports_inbox set group_open=false where recipient_user_id=new.user_id and room_id=new.room_id and group_open and activity_at<=new.last_read_at;
   end if;return new;
  end if;
  if new.member_kind<>'account' or new.user_id=new.added_by then return new;end if;
  -- Accepted invitations already have their own story.
  if exists(select 1 from public.nothingsports_chat_invitations where room_id=new.room_id and invitee_id=new.user_id) then return new;end if;
  insert into public.nothingsports_inbox(recipient_user_id,kind,source_key,actor_user_id,room_id)
  values(new.user_id,'added','member:'||new.room_id||':'||new.joined_at,new.added_by,new.room_id) on conflict do nothing;return new;
 elsif tg_table_name='nothingsports_chat_invitations' then
  if new.status<>'pending' then return new;end if;
  insert into public.nothingsports_inbox(recipient_user_id,kind,source_key,actor_user_id,room_id)
  values(new.invitee_id,'invitation','invitation:'||new.invitation_id,new.inviter_id,new.room_id) on conflict do nothing;return new;
 elsif tg_table_name='nothingsports_social_notifications' then
  k:=new.kind;recipient:=new.recipient_user_id;actor:=new.actor_user_id;pts:=new.points;source:='social:'||new.id;
 elsif tg_table_name='nothingsports_nsc_points' then
  if new.action_key in ('followed_by_person','picks_copied') then return new;end if;
  k:='points';recipient:=new.user_id;pts:=new.points;source:='points:'||new.ledger_id;
 elsif tg_table_name='nothingsports_friend_activity' then
  k:='rating';recipient:=new.recipient_user_id;actor:=new.rater_user_id;source:='rating:'||new.id;
 end if;
 if recipient is not null then
  insert into public.nothingsports_inbox(recipient_user_id,kind,source_key,actor_user_id,event_id,phase,points,detail)
  values(recipient,k,source,actor,j->>'event_id',j->>'phase',pts,case when k='points' then j->>'action_key' end) on conflict do nothing;
 end if;return new;
end $function$

CREATE OR REPLACE FUNCTION public.nothingsports_nsc_lock_submitted_contribution()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if tg_op='UPDATE' and (new.event_id<>old.event_id or new.user_id<>old.user_id or new.phase<>old.phase or new.bucket_start<>old.bucket_start) then raise exception 'immutable_contribution_identity';end if;
 if new.phase in('heat','impact') and new.submitted_at is null then new.submitted_at:=now();end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.nothingsports_guard_erasure_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid;actors uuid[]:='{}';column_name text;null_only boolean:=false;
begin
 if current_setting('transaction_isolation')<>'read committed' then
  raise exception using errcode='25000',message='account_erasure_guard_requires_read_committed';
 end if;
 -- FK SET NULL actions must be able to detach attribution during Auth deletion,
 -- even when another column in the same row still references that account.
 if tg_op='UPDATE' then
  null_only:=(to_jsonb(new)-tg_argv)=(to_jsonb(old)-tg_argv) and to_jsonb(new)<>to_jsonb(old);
  -- Auth FK detachment may also erase this subject's copied audit snapshots.
  -- Only this table, a removed target, empty snapshots and otherwise unchanged
  -- content qualify; arbitrary edits still pass through the erasure barrier.
  if tg_table_schema='public' and tg_table_name='nothingsports_nsc_admin_audit'
     and to_jsonb(old)->>'target_user_id' is not null
     and to_jsonb(new)->>'target_user_id' is null
     and to_jsonb(new)->'before_state'='{}'::jsonb
     and to_jsonb(new)->'after_state'='{}'::jsonb then
   null_only:=(to_jsonb(new)-tg_argv-array['before_state','after_state'])
             =(to_jsonb(old)-tg_argv-array['before_state','after_state']);
  end if;
  foreach column_name in array tg_argv loop
   if (to_jsonb(new)->column_name) is distinct from (to_jsonb(old)->column_name)
      and (to_jsonb(new)->>column_name) is not null then null_only:=false;end if;
  end loop;
  if null_only then return new;end if;
 end if;
 foreach column_name in array tg_argv loop
  actor:=(to_jsonb(new)->>column_name)::uuid;
  if actor is not null then actors:=array_append(actors,actor);end if;
 end loop;
 for actor in select distinct a from unnest(actors) a order by a loop
  -- The shared transaction lock drains already-accepted writes before begin returns.
  perform pg_catalog.pg_advisory_xact_lock_shared(pg_catalog.hashtextextended('account-erasure:'||actor::text,0));
  if exists(select 1 from public.nothingsports_account_erasure_blocks b where b.user_id=actor) then
   raise exception using errcode='55000',message='account_erasure_in_progress';
  end if;
 end loop;
 return new;
end $function$
